float Processor::value(const String& id)const{if(auto* p=state.getRawParameterValue(id))return p->load();if(id.startsWith("macro"))return macroValue(id.getTrailingIntValue()-1);return 0;}
void Processor::set(const String& id,float v){if(!std::isfinite(v))return;if(auto* p=state.getParameter(id)){p->beginChangeGesture();p->setValueNotifyingHost(p->convertTo0to1(v));p->endChangeGesture();}else if(id.startsWith("macro"))setMacroValue(id.getTrailingIntValue()-1,v);}
float Processor::dspValue(const String& id)const{auto found=indices.find(id);return found==indices.end()?0:effective[found->second];}
