int Processor::macroCount()const{auto r=macros();int count=jmax(4,r->visibleCount);for(int i=4;i<(int)r->names.size();++i)if(r->names[i].isNotEmpty()||macroValue(i)!=0)count=jmax(count,i+1);for(auto& link:r->links)count=jmax(count,link.macro+1);return count;}
void Processor::addMacro(){auto n=std::make_shared<noctrl::MacroRouting>(*macros());n->visibleCount=macroCount()+1;n->ensureSize(n->visibleCount);std::atomic_store(&macroState,std::shared_ptr<const noctrl::MacroRouting>(n));updateHostDisplay(ChangeDetails{}.withNonParameterStateChanged(true));}
float Processor::macroValue(int m)const{if(m<0)return 0;if(m<8)return raw[ix.macro[m]]->load();auto r=macros();return m<(int)r->names.size()?r->extra[m-8]->get():0;}
void Processor::setMacroValue(int m,float v){if(!std::isfinite(v)||m<0||m>=(int)macros()->names.size())return;if(m<8)state.getParameter("macro"+String(m+1))->setValueNotifyingHost(jlimit(0.f,1.f,v));else{*macros()->extra[m-8]=jlimit(0.f,1.f,v);updateHostDisplay(ChangeDetails{}.withNonParameterStateChanged(true));}}
void Processor::setMacroInfo(int m,String name,Colour colour){auto n=std::make_shared<noctrl::MacroRouting>(*macros());if(m<0||m>=(int)n->names.size())return;n->names[m]=name.trim().substring(0,32);n->colours[m]=colour.withAlpha(1.f).getARGB();std::atomic_store(&macroState,std::shared_ptr<const noctrl::MacroRouting>(n));updateHostDisplay(ChangeDetails{}.withNonParameterStateChanged(true));}
bool Processor::assignMacro(int m,const String& id){auto* p=state.getParameter(id);if(m<0||m>=(int)macros()->names.size()||!p||id.startsWith("macro")||dynamic_cast<AudioParameterBool*>(p)||dynamic_cast<AudioParameterChoice*>(p)||dynamic_cast<AudioParameterInt*>(p))return false;auto n=std::make_shared<noctrl::MacroRouting>(*macros());auto found=std::find_if(n->links.begin(),n->links.end(),[&](auto& l){return l.target==id;});float start=p->getValue();noctrl::MacroLink link{m,p->getParameterIndex(),id,start,start>.75f?jmax(0.f,start-.25f):jmin(1.f,start+.25f),p};if(found==n->links.end())n->links.push_back(link);else found->macro=m;std::atomic_store(&macroState,std::shared_ptr<const noctrl::MacroRouting>(n));updateHostDisplay(ChangeDetails{}.withNonParameterStateChanged(true));return true;}
void Processor::removeMacroLinks(int m){auto links=macros()->links;for(auto& link:links)if(link.macro==m)removeMacroLink(link.target);}
void Processor::removeMacroLink(const String& id){auto n=std::make_shared<noctrl::MacroRouting>(*macros());n->links.erase(std::remove_if(n->links.begin(),n->links.end(),[&](auto& l){return l.target==id;}),n->links.end());std::atomic_store(&macroState,std::shared_ptr<const noctrl::MacroRouting>(n));updateHostDisplay(ChangeDetails{}.withNonParameterStateChanged(true));}
void Processor::setMacroRange(const String& id,float a,float b){if(!std::isfinite(a)||!std::isfinite(b))return;auto n=std::make_shared<noctrl::MacroRouting>(*macros());for(auto& l:n->links)if(l.target==id){l.start=jlimit(0.f,1.f,a);l.end=jlimit(0.f,1.f,b);}std::atomic_store(&macroState,std::shared_ptr<const noctrl::MacroRouting>(n));updateHostDisplay(ChangeDetails{}.withNonParameterStateChanged(true));}
