void Processor::getStateInformation(MemoryBlock& b){auto t=state.copyState();t.removeChild(t.getChildWithName("MacroRouting"),nullptr);t.addChild(macros()->save(),-1,nullptr);t.setProperty("editorPage",editorPage.load(),nullptr);if(auto xml=t.createXml())copyXmlToBinary(*xml,b);}
bool Processor::restore(const void* data,int size){if(size<1||size>64*1024*1024)return false;auto xml=getXmlFromBinary(data,size);if(!xml||!xml->hasTagName("NEXUM_GATE"))return false;auto source=ValueTree::fromXml(*xml);ValueTree clean("NEXUM_GATE");for(auto* p:params){auto child=source.getChildWithProperty("id",p->getParameterID());float v=(float)child.getProperty("value",p->convertFrom0to1(p->getDefaultValue()));if(!std::isfinite(v))return false;auto r=p->getNormalisableRange();v=jlimit(r.start,r.end,v);ValueTree node("PARAM");node.setProperty("id",p->getParameterID(),nullptr);node.setProperty("value",p->convertFrom0to1(p->convertTo0to1(v)),nullptr);clean.addChild(node,-1,nullptr);}for(auto prop:{"presetName","author","category","description","notes","tags","rating"})clean.setProperty(prop,source.getProperty(prop),nullptr);const ScopedLock lock(getCallbackLock());state.replaceState(clean);restoreMacros(source.getChildWithName("MacroRouting"));editorPage.store(jlimit(0,1,(int)source.getProperty("editorPage",0)));resetRuntime();updateEffective(0);for(auto& link:macros()->links)smoothing[link.index].setCurrentAndTargetValue(link.normalized(macroValue(link.macro)));return true;}
void Processor::setStateInformation(const void* data,int size){restore(data,size);}
StringArray Processor::factoryNames(){return {"Init","Clean Duck","Classic Trance","Psy Pulse","Slow Swell","Stereo Motion","Broken Beat","Triplet Flow"};}
void Processor::factory(int preset){preset=jlimit(0,7,preset);const ScopedLock lock(getCallbackLock());for(auto* p:params)p->setValueNotifyingHost(p->getDefaultValue());restoreMacros({});for(int slot=0;slot<8;++slot)fillPattern(slot,(preset+slot)%8);if(preset==1){set("gateOn",0);set("duckDepth",1);}if(preset==2){set("duckOn",0);set("gateDepth",1);}if(preset==3){set("duckRate",1);set("gateDepth",1);set("release",.004f);}if(preset==4){set("duckShape",14);set("duckRate",11);set("attack",.08f);set("release",.15f);set("gateDepth",.45f);}if(preset==5){set("gateOn",0);set("duckDepth",.4f);set("panOn",1);set("panRate",11);}if(preset==7)set(slotId(0,"resolution"),6);state.state.setProperty("presetName",factoryNames()[preset],nullptr);state.state.setProperty("author","NEXUM",nullptr);for(auto id:{"category","description","notes","tags"})state.state.setProperty(id,"",nullptr);state.state.setProperty("rating",0,nullptr);resetRuntime();updateEffective(0);}
void Processor::fillPattern(int slot,int kind){if(slot<0||slot>=8)return;const String patterns[]={"1010101010101010","1110101011101010","0011001100110011","1011010110110101","1000101110001101","1111000011110000","101011101011","1111111100001010"};kind=jlimit(0,7,kind);auto text=patterns[kind];set(slotId(slot,"length"),(float)text.length());set(slotId(slot,"resolution"),kind==6?6.f:2.f);for(int k=0;k<64;++k){bool on=text[k%text.length()]=='1';set(stepId(slot,k),on?1:0);set(stepId(slot,k,true),(kind==2||kind==5)&&on&&text[(k+1)%text.length()]=='1'?1:0);}}
void Processor::copyPattern(int from,int to){if(from==to||from<0||to<0||from>=8||to>=8)return;for(auto suffix:{"length","resolution"})set(slotId(to,suffix),value(slotId(from,suffix)));for(int k=0;k<64;++k){set(stepId(to,k),value(stepId(from,k)));set(stepId(to,k,true),value(stepId(from,k,true)));}}
void Processor::selectShape(int shape){set("duckShape",(float)jlimit(0,15,shape));set("custom",0);for(int i=0;i<33;++i)set("curve"+String(i),envelope(i/32.f,jlimit(0,15,shape)));}
float Processor::curve(float phase)const{if(value("custom")<.5f)return envelope(phase,(int)value("duckShape"));float at=jlimit(0.f,1.f,phase)*32;int a=jlimit(0,31,(int)at);return value("curve"+String(a))+(value("curve"+String(a+1))-value("curve"+String(a)))*(at-a);}
